import { decide, type AdaptiveHost } from
  '../../../src/services/tools/adaptive-sandbox.service.js';
import type { AdaptiveSignals } from
  '../../../src/services/tools/adaptive-sandbox.types.js';

const REAL: Record<string, string> = {
  '/data/reports': '/data/reports',
  '/data/link': '/data/reports',          // symlink → 正当目录
  '/home/u/.ssh': '/home/u/.ssh',
  '/etc/passwd': '/etc/passwd',
  '/repo/tests': '/repo/tests',
};
const host: AdaptiveHost = {
  realpath: (p) => { const r = REAL[p]; if (!r) throw new Error('enoent'); return r; },
  validateAllowDir: (r) => r === '/data/reports',
  isSensitivePath: (r) => r.includes('.ssh'),
  isRestricted: (r) => r.startsWith('/etc'),
  isProtected: (r) => r.startsWith('/repo/tests'),
  boundaryOf: (s) => s === 'sys.exec' ? 'never_exempt'
    : s === 'fs.write' ? 'approval_required' : 'autonomous',
  driftDetected: () => false,
  now: () => 1_000_000,
  uuid: (() => { let n = 0; return () => `id-${++n}`; })(),
};
const base: AdaptiveSignals = {
  taskId: 't1', requestedPath: '/data/reports',
  taskContextRefs: ['/data/reports'], riskFlags: [], history: [],
};

// G1 正当放行（含 symlink 归一）
console.assert(decide(host, base).verdict === 'allow_readonly_temp', 'G1a');
console.assert(decide(host, { ...base, requestedPath: '/data/link' })
  .verdict === 'allow_readonly_temp', 'G1b');

// G2 越界仍拒（上下文未引用）
console.assert(decide(host, { ...base, taskContextRefs: [] })
  .verdict === 'deny', 'G2');

// G3 敏感路径永不放行（即使上下文明确引用）
console.assert(decide(host, { ...base, requestedPath: '/home/u/.ssh',
  taskContextRefs: ['/home/u/.ssh'] }).verdict === 'deny', 'G3a');
console.assert(decide(host, { ...base, requestedPath: '/etc/passwd',
  taskContextRefs: ['/etc/passwd'] }).verdict === 'deny', 'G3b');
console.assert(decide(host, { ...base, requestedPath: '/repo/tests',
  taskContextRefs: ['/repo/tests'] }).verdict === 'deny', 'G3c');

// G4 sys.exec 永不豁免 + 写永不自动放行
console.assert(host.boundaryOf('sys.exec') === 'never_exempt', 'G4a');
console.assert(decide(host, { ...base, riskFlags: ['write_intent'] })
  .verdict === 'escalate_to_human', 'G4b');
console.assert(decide(host, { ...base, riskFlags: ['exec_in_task'] })
  .verdict === 'escalate_to_human', 'G4c');

// G5 可审计可回滚
const d = decide(host, base);
console.assert(d.auditId.length > 0 && d.rollbackToken !== null, 'G5a');
const afterRevoke = decide(host, { ...base,
  history: [{ path: '/data/reports', action: 'revoked', at: 1 }] });
console.assert(afterRevoke.verdict === 'escalate_to_human', 'G5b');
// G6 漂移冻结
console.assert(decide({ ...host, driftDetected: () => true }, base)
  .verdict === 'escalate_to_human', 'G6');
```

